local BottomFullerMaker = {}
local PRODUCTS = {
    iron_bottomfuller = { name = "Železni spodnji fuller za utorjanje", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni spodnji fuller za utorjanje za kovace." },
    bronze_bottomfuller = { name = "Bronast spodnji fuller za utorjanje", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast spodnji fuller za utorjanje za kovace." },
    silver_bottomfuller = { name = "Srebrn spodnji fuller za utorjanje", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn spodnji fuller za utorjanje za kovace." },
    gilded_bottomfuller = { name = "Pozlačen spodnji fuller za utorjanje", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen spodnji fuller za utorjanje za kovace." },
    jewel_set_bottomfuller = { name = "Draguljast spodnji fuller za utorjanje", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast spodnji fuller za utorjanje za kovace." },
    royal_sovereign_bottomfuller = { name = "Kraljevski suveren spodnji fuller za utorjanje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren spodnji fuller za utorjanje z biseri za krono." },
}
local BUILDINGS = {
    bottomfuller_workshop = { name = "Bottomfuller delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    bottomfuller_house = { name = "Bottomfuller hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_bottomfuller_atelier = { name = "Mojstrski bottomfuller atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_bottomfuller_palace = { name = "Suverena bottomfuller palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
BottomFullerMaker.ironStock=18; BottomFullerMaker.bronzeStock=14; BottomFullerMaker.woodStock=10; BottomFullerMaker.leatherStock=8; BottomFullerMaker.silverStock=8; BottomFullerMaker.goldStock=6; BottomFullerMaker.jewelStock=4; BottomFullerMaker.pearlStock=4
BottomFullerMaker.productStock = {}; BottomFullerMaker.buildings = {}; BottomFullerMaker.maker = nil; BottomFullerMaker.activeMaking = {}; BottomFullerMaker.totalProducts = 0; BottomFullerMaker.dayTimer = 0
function BottomFullerMaker.init() BottomFullerMaker.ironStock=18; BottomFullerMaker.bronzeStock=14; BottomFullerMaker.woodStock=10; BottomFullerMaker.leatherStock=8; BottomFullerMaker.silverStock=8; BottomFullerMaker.goldStock=6; BottomFullerMaker.jewelStock=4; BottomFullerMaker.pearlStock=4; BottomFullerMaker.productStock={}; BottomFullerMaker.buildings={}; BottomFullerMaker.maker=nil; BottomFullerMaker.activeMaking={}; BottomFullerMaker.totalProducts=0; BottomFullerMaker.dayTimer=0; print("[BottomFullerMaker] Royal Bottom Fuller Maker System initialized (6 products, 4 buildings)") end
function BottomFullerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BottomFullerMaker.maker={name=n or ("SpodnjiUtor "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("SpodnjiUtor najet: %s (spretnost: %d)",BottomFullerMaker.maker.name,s),"success") end; return true end
function BottomFullerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BottomFullerMaker.build(id) local ok,e=BottomFullerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BottomFullerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BottomFullerMaker.getQualityBonus() local b=0; for _,bd in ipairs(BottomFullerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BottomFullerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BottomFullerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BottomFullerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BottomFullerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BottomFullerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BottomFullerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BottomFullerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BottomFullerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BottomFullerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BottomFullerMaker.buildings==0 then return false,"Potrebna spodnjeutorjalna delavnica" end; if not BottomFullerMaker.maker then return false,"Potreben spodnjiutor" end; return true end
function BottomFullerMaker.make(pt,qty) qty=qty or 1; local ok,e=BottomFullerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BottomFullerMaker.ironStock=BottomFullerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BottomFullerMaker.bronzeStock=BottomFullerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BottomFullerMaker.woodStock=BottomFullerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BottomFullerMaker.leatherStock=BottomFullerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BottomFullerMaker.silverStock=BottomFullerMaker.silverStock-d.silverCost*qty end; if d.goldCost then BottomFullerMaker.goldStock=BottomFullerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BottomFullerMaker.jewelStock=BottomFullerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BottomFullerMaker.pearlStock=BottomFullerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BottomFullerMaker.maker then t=math.max(1,t-math.floor(BottomFullerMaker.maker.skill/13)) end; table.insert(BottomFullerMaker.activeMaking,{id="bottomfuller_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BottomFullerMaker.completeMaking(m) local q=1.0+(BottomFullerMaker.getQualityBonus()/100); if BottomFullerMaker.maker then q=q+(BottomFullerMaker.maker.skill/140) end; q=math.min(2.5,q); BottomFullerMaker.productStock[m.productType]=(BottomFullerMaker.productStock[m.productType] or 0)+m.quantity; BottomFullerMaker.totalProducts=BottomFullerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BottomFullerMaker.maker then BottomFullerMaker.maker.itemsMade=BottomFullerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BottomFullerMaker.maker.skill=math.min(100,BottomFullerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("SpodnjiUtor izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bottomfuller.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BottomFullerMaker.update(dt) if not _G.state then return end; BottomFullerMaker.dayTimer=BottomFullerMaker.dayTimer+dt; if BottomFullerMaker.dayTimer>=30 then BottomFullerMaker.dayTimer=0; for i=#BottomFullerMaker.activeMaking,1,-1 do local m=BottomFullerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BottomFullerMaker.completeMaking(m); table.remove(BottomFullerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BottomFullerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BottomFullerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BottomFullerMaker.getStats() return {ironStock=BottomFullerMaker.ironStock,bronzeStock=BottomFullerMaker.bronzeStock,woodStock=BottomFullerMaker.woodStock,leatherStock=BottomFullerMaker.leatherStock,silverStock=BottomFullerMaker.silverStock,goldStock=BottomFullerMaker.goldStock,jewelStock=BottomFullerMaker.jewelStock,pearlStock=BottomFullerMaker.pearlStock,productStock=BottomFullerMaker.productStock,numBuildings=#BottomFullerMaker.buildings,hasMaker=BottomFullerMaker.maker~=nil,makerName=BottomFullerMaker.maker and BottomFullerMaker.maker.name or "—",makerSkill=BottomFullerMaker.maker and BottomFullerMaker.maker.skill or 0,activeMaking=#BottomFullerMaker.activeMaking,totalProducts=BottomFullerMaker.totalProducts} end
return BottomFullerMaker
